// The construct suite through the checker path (ADR 0026): `caliper-docgen extract --experimental-semantic-types` with a
// `tsrs` binary over apps/oracle/construct-suite, and each row's verdict against its golden. It is evidence for the
// slice that makes the checker the default (S4), not a gate: it prints, it does not fail on a row, and it is not a CI
// job. Run it by hand:
//
//   cargo build --release -p caliper-docgen
//   CALIPER_SEMANTIC=1 TSRS_BIN=<node_modules/@tsrs/<platform>/tsrs> pnpm --filter caliper-docgen-oracle construct:checker
//
// A row the checker did not answer for (it kept the structural result) is listed apart: its verdict says nothing about
// the checker. `--json <file>` also writes every row with the type each side gave.
import { execFileSync } from 'node:child_process'
import { existsSync, readFileSync, realpathSync, writeFileSync } from 'node:fs'
import { join, resolve } from 'node:path'
import { checkCaliperShape, flattenProps } from './caliper-input.ts'
import {
  GREEN,
  listFixtures,
  PROP,
  rowVerdict,
  type Expectation,
  type Golden,
  type RowVerdict,
} from './construct-suite.ts'

if (process.env.CALIPER_SEMANTIC !== '1') {
  console.error('construct-checker-lane: set CALIPER_SEMANTIC=1 (and TSRS_BIN) to run the suite through the checker.')
  process.exit(2)
}
const tsrs = process.env.TSRS_BIN
if (!tsrs || !existsSync(tsrs)) {
  console.error(`construct-checker-lane: TSRS_BIN must name a tsrs binary (got ${JSON.stringify(tsrs)}).`)
  process.exit(2)
}
const bin = resolve(
  process.env.CALIPER_BIN ?? join(import.meta.dirname, '..', '..', '..', 'target', 'release', 'caliper-docgen'),
)
if (!existsSync(bin)) {
  console.error(`construct-checker-lane: no caliper binary at ${bin}; build one or set CALIPER_BIN.`)
  process.exit(2)
}

const suite = realpathSync(join(import.meta.dirname, '..', 'construct-suite'))
const expectations: { rows: Record<string, Expectation> } = JSON.parse(
  readFileSync(join(suite, 'expectations.json'), 'utf8'),
)
const jsonOut = process.argv.includes('--json') ? process.argv[process.argv.indexOf('--json') + 1] : undefined

function extract(extra: string[]): any {
  const stdout = execFileSync(
    bin,
    [
      'extract',
      '--src',
      suite,
      '--json',
      '--html-attributes',
      'full',
      '--include-unexported',
      '--load-dependencies',
      '--collapse-inherited-props',
      'none',
      '--no-cache',
      '--quiet',
      ...extra,
    ],
    { encoding: 'utf8', maxBuffer: 512 * 1024 * 1024 },
  )
  const caliper = JSON.parse(stdout)
  checkCaliperShape(caliper)
  return caliper
}

const started = performance.now()
const checked = extract(['--experimental-semantic-types', '--tsc-path', tsrs])
const elapsedMs = Math.round(performance.now() - started)

/** The component keys the checker answered for, from the provenance diagnostic the merge writes. */
const answered = new Set<string>()
for (const diagnostic of checked.diagnostics ?? []) {
  if (String(diagnostic.message).includes('resolved by the TypeScript checker')) {
    // `affects` is a list of component keys, or the id of one in `nameLists` (the canonical JSON shares repeated lists).
    const affects = typeof diagnostic.affects === 'string' ? checked.nameLists[diagnostic.affects] : diagnostic.affects
    for (const key of affects ?? []) answered.add(key)
  }
}
const backendProblems = (checked.diagnostics ?? []).filter((d: any) =>
  String(d.message).includes('checker backend unavailable'),
)
if (backendProblems.length > 0) {
  console.error(`construct-checker-lane: the checker was unavailable: ${backendProblems[0].message}`)
  process.exit(1)
}

interface Row {
  id: string
  verdict: RowVerdict
  structural: RowVerdict[]
  answered: boolean
  type: unknown
  degradedBy: unknown
  golden: string
}

const byFile = new Map<string, { key: string; prop: any }>()
for (const [key, component] of Object.entries<any>(checked.components)) {
  if (component.displayName !== 'Row') continue
  const id = flattenProps(checked, key, component)[PROP]
  byFile.set(realpathSync(component.filePath), { key, prop: id === undefined ? undefined : checked.props[id] })
}

const rows: Row[] = []
for (const fixture of listFixtures(suite)) {
  const golden: Golden = JSON.parse(readFileSync(fixture.golden, 'utf8'))
  const found = byFile.get(realpathSync(fixture.file))
  rows.push({
    id: fixture.id,
    verdict: rowVerdict(found?.prop, golden),
    structural: expectations.rows[fixture.id]?.verdicts ?? [],
    answered: found !== undefined && answered.has(found.key),
    type: found?.prop?.type,
    degradedBy: found?.prop?.degradedBy,
    golden: golden.text,
  })
}

const checkerRows = rows.filter((row) => row.answered)
const structuralRows = rows.filter((row) => !row.answered)
const green = (row: Row) => GREEN.includes(row.verdict)
console.log(
  `checker path over ${rows.length} rows in ${elapsedMs} ms: ${checkerRows.length} answered by the checker, ${structuralRows.length} kept their structural result`,
)
const count = (list: Row[]) => {
  const tally = new Map<string, number>()
  for (const row of list) tally.set(row.verdict, (tally.get(row.verdict) ?? 0) + 1)
  return [...tally].map(([verdict, n]) => `${verdict} ${n}`).join(', ')
}
console.log(`  checker rows: ${count(checkerRows)}`)
console.log('')
console.log('Rows the checker answered that are not identical or spelled (verdict | structural expectation | golden):')
for (const row of checkerRows.filter((r) => !green(r))) {
  console.log(`  ${row.id}: ${row.verdict} | ${row.structural.join('/')} | ${row.golden}`)
}
console.log('')
console.log('Rows the checker answered that the structural result did not get green (improvements):')
for (const row of checkerRows.filter((r) => green(r) && !r.structural.every((v) => GREEN.includes(v)))) {
  console.log(`  ${row.id}: ${row.verdict} (structural: ${row.structural.join('/')})`)
}
console.log('')
console.log('Rows that kept their structural result (no checker verdict):')
for (const row of structuralRows) console.log(`  ${row.id}: ${row.verdict}`)

if (jsonOut) writeFileSync(jsonOut, JSON.stringify({ elapsedMs, rows }, null, 2))
// The deterministic construct suite's pure half (apps/oracle/construct-suite/README.md): which fixtures exist, the verdict
// one of Caliper's props earns against its golden, and the check of the expectations file. Nothing here runs the checker
// or Caliper, so tests/construct-suite.test.ts can pin it without either.
import { readdirSync } from 'node:fs'
import { join } from 'node:path'
import { caliperNorm } from './caliper-norm.ts'
import { compare, type Norm, type Verdict } from './oracle-compare.ts'

/** The prop every fixture states its type through. */
export const PROP = 'p'

/** What the suite says about a row: the comparison's verdict, plus the two cases it cannot make. `opaque with marker`
 * is a type Caliper left unevaluated and said so (`degradedBy`); `missing` is a prop Caliper did not list. */
export type RowVerdict = Verdict | 'opaque with marker' | 'missing'

export const GREEN: RowVerdict[] = ['identical', 'spelled']

/** Best to worst. A row whose verdict moved down this list got worse; up, better. `checker any/error` is a fixture
 * problem (the golden has no type), ranked last so it never reads as an improvement. */
export const ORDER: RowVerdict[] = [
  'identical',
  'spelled',
  'opaque with marker',
  'less precise',
  'wrong',
  'missing',
  'checker any/error',
]

/** What `--check` and the test read back from `<name>.golden.json`. */
export interface Golden {
  /** The checker's type of prop `p`, normalized by src/oracle-checker.ts. */
  checker: Norm
  /** `checker.typeToString` of the same type, for the reader of a diff. */
  text: string
}

export interface Fixture {
  /** `<family>/<NN>-<slug>`: the row id the expectations file keys on. */
  id: string
  /** The fixture's absolute path. */
  file: string
  /** The golden's absolute path, next to the fixture. */
  golden: string
}

const FIXTURE = /^\d{2}-[a-z0-9][a-z0-9-]*\.tsx$/

/** Every `<family>/<NN>-<slug>.tsx` under `dir`, sorted by id. A `.tsx` whose name breaks the pattern is an error, not a
 * row that quietly never runs. */
export function listFixtures(dir: string): Fixture[] {
  const fixtures: Fixture[] = []
  for (const family of readdirSync(dir, { withFileTypes: true })) {
    if (!family.isDirectory()) continue
    for (const entry of readdirSync(join(dir, family.name))) {
      if (!entry.endsWith('.tsx')) continue
      if (!FIXTURE.test(entry)) {
        throw new Error(`${family.name}/${entry}: a fixture is named <NN>-<slug>.tsx (lowercase)`)
      }
      const file = join(dir, family.name, entry)
      fixtures.push({
        id: `${family.name}/${entry.replace(/\.tsx$/, '')}`,
        file,
        golden: file.replace(/\.tsx$/, '.golden.json'),
      })
    }
  }
  return fixtures.toSorted((a, b) => (a.id < b.id ? -1 : 1))
}

/** The verdict for Caliper's prop against the golden. A prop with `degradedBy` that is only `less precise` is an
 * `opaque with marker`: Caliper said it did not evaluate the type. A `wrong` prop stays wrong with or without a marker. */
export function rowVerdict(prop: { type: unknown; degradedBy?: unknown } | undefined, golden: Golden): RowVerdict {
  if (prop === undefined) return 'missing'
  const verdict = compare(caliperNorm(prop.type), golden.checker)
  const marked = Array.isArray(prop.degradedBy) && prop.degradedBy.length > 0
  return marked && verdict === 'less precise' ? 'opaque with marker' : verdict
}

export interface Expectation {
  /** The verdicts the row may have; the test fails on any other. */
  verdicts: RowVerdict[]
  /** Why Caliper falls short of the checker here. Present exactly on a documented gap. */
  gap?: string
}

/** Problems with the expectations against the fixtures; empty when they agree. */
export function expectationProblems(ids: string[], rows: Record<string, Expectation>): string[] {
  const problems: string[] = []
  for (const id of ids) {
    const row = rows[id]
    if (row === undefined) {
      problems.push(`${id}: no entry in expectations.json`)
      continue
    }
    if (!Array.isArray(row.verdicts) || row.verdicts.length === 0) {
      problems.push(`${id}: "verdicts" must list at least one verdict`)
      continue
    }
    const unknown = row.verdicts.filter((v) => !ORDER.includes(v))
    if (unknown.length > 0) problems.push(`${id}: unknown verdict ${unknown.join(', ')}`)
    const green = row.verdicts.every((v) => GREEN.includes(v))
    const anyGreen = row.verdicts.some((v) => GREEN.includes(v))
    if (green && row.gap !== undefined) problems.push(`${id}: a green row carries no "gap"`)
    if (!green && anyGreen) {
      problems.push(`${id}: a gap must not allow identical or spelled, or an improvement goes unnoticed`)
    }
    if (!anyGreen && (typeof row.gap !== 'string' || row.gap.trim() === '')) {
      problems.push(`${id}: a row that is not identical or spelled is a documented gap and needs a "gap" reason`)
    }
  }
  const known = new Set(ids)
  for (const id of Object.keys(rows)) if (!known.has(id)) problems.push(`${id}: expectation without a fixture`)
  return problems
}

/** Null when `verdict` is allowed; otherwise what moved, for the failure message. */
export function expectationFailure(id: string, verdict: RowVerdict, row: Expectation): string | null {
  if (row.verdicts.includes(verdict)) return null
  const rank = (v: RowVerdict) => ORDER.indexOf(v)
  const here = rank(verdict)
  let direction = 'unexpected'
  if (here < Math.min(...row.verdicts.map(rank))) direction = 'better than expected: update expectations.json'
  else if (here > Math.max(...row.verdicts.map(rank))) direction = 'worse than expected: a regression'
  return `${id}: ${verdict} (${direction}; allowed ${row.verdicts.join(' | ')})`
}
